setTimeout(() => {
    //console.clear()
    url = "data:image/png;base64,"
    image = new Image();
    size = 48
    sizew = 48//00
    image.src = url;
    image.onload = function () {
        var style = [
            'font-size: 1px;',
            'padding: ' + this.height / 100 * size + 'px ' + this.width / 100 * sizew + 'px;',
            'background: url(' + url + ') repeat;',
            //'background-size: contain;'
        ].join(' ');
        console.log('%c ', style);
        
        setTimeout(()=>{
            console.log('%c ', style);
            console.log('%c ', style);
        },5000)
        setTimeout(()=>{
            console.log('%c ', style);
            console.log('%c ', style);
        },10000)
        setInterval(()=>{
            console.log('%c ', style);
        },60000)
    }
}, 1000);